const float PI = 2.0*acos(0.0);
const float SQRT3 = sqrt(3.0);
const mat2 ROT1 = mat2(cos(PI/1.5),sin(PI/1.5),-sin(PI/1.5),cos(PI/1.5));
const mat2 ROT2 = mat2(cos(PI/6.0),sin(PI/6.0),-sin(PI/6.0),cos(PI/6.0));

// Funzione per generare colori che cambiano lentamente
vec3 cyclicColor(float time) {
    float slowTime = time * 0.1; // Rallentato significativamente
    return vec3(
        0.3 + 0.2 * sin(slowTime * 0.5),
        0.3 + 0.2 * sin(slowTime * 0.7 + PI/3.0),
        0.3 + 0.2 * sin(slowTime * 0.9 + PI/1.5)
    );
}

float fractal(vec2 x, float param) {
    if (x.y < -0.0 || x.y/(0.25*SQRT3)+abs(x.x)*4.0/3.0 > 2.0) {
        return -1.0;
    }

    float t = 1.0;
    for (int i=0; i<6; i++) {
        if (x.y/(0.25*SQRT3)+abs(x.x)*4.0 < 2.0) {
            if (x.y > 1.0/SQRT3) {
                x = x*3.0-vec2(0.0,SQRT3);
            } else if(x.x+x.y/SQRT3 < -1.0/6.0) {
                x = x*3.0+vec2(1.0,0.0);
            } else if(-x.x+x.y/SQRT3 < -1.0/6.0) {
                x = ROT1*ROT1*(x*3.0-vec2(1.0,0.0))+vec2(-0.25,0.25*SQRT3);
                t = 1.0-t;
            } else if(x.x < 1.0/6.0 && x.x+min(x.y,1.0/SQRT3-x.y)*SQRT3 > 1.0/6.0) {
                x = mat2(1.5,0.5*SQRT3,-0.5*SQRT3,1.5)*(x-vec2(0.0,0.5/SQRT3))+vec2(0.0,0.5/SQRT3);
                t = 1.0-t;
            } else {
                if (x.x < 1.0/6.0) {
                    if (x.y > 0.5/SQRT3) {
                        x = ROT1*ROT1*(x-vec2(0.0,0.5/SQRT3))+vec2(0.0,0.5/SQRT3);
                    } else {
                        x = ROT1*(x-vec2(0.0,0.5/SQRT3))+vec2(0.0,0.5/SQRT3);
                        t = 1.0-t;
                    }
                }
                x = mat2(0.0,SQRT3,-SQRT3,0.0)*(x-vec2(0.0,0.5/SQRT3))+vec2(0.0,0.5/SQRT3);
                t = 1.0-t;
            }
        } else {
            if (x.x < 0.0) {
                x = ROT1*ROT2*(x+vec2(0.5,0.0))*SQRT3+vec2(0.0,0.5*SQRT3);
            } else {
                x = ROT2*ROT2*ROT1*ROT2*(x-vec2(0.5,0.0))*SQRT3+vec2(0.0,0.5*SQRT3);
            }
            if (x.y/(0.25*SQRT3)+abs(x.x)*4.0 > 2.0) {
                if (x.x < 0.0) {
                    x = ROT1*ROT2*(x+vec2(0.5,0.0))*SQRT3+vec2(0.0,0.5*SQRT3);
                } else {
                    x = ROT2*ROT2*ROT1*ROT2*(x-vec2(0.5,0.0))*SQRT3+vec2(0.0,0.5*SQRT3);
                }
            }
        }
    }

    // Movimento più fluido nella trasformazione finale
    float smoothParam = smoothstep(0.0, 1.0, param);
    x = (smoothParam*mat2(1.0,sin(param*PI*0.5),-sin(param*PI*0.5),1.0)
         +(1.0-smoothParam)*mat2(0.5,-0.5*SQRT3,0.5/SQRT3,1.5))
        *(x-vec2(0.5,0.0))+vec2(0.5,0.0);

    return ((x.y>1.0/SQRT3||x.x+x.y*SQRT3<1.0/6.0||x.y/(0.25*SQRT3)+abs(x.x)*4.0>2.0)?t:1.0-t);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord-iResolution.xy/2.0)/length(iResolution);

    // Colori ciclici più lenti
    vec3 col = cyclicColor(iTime);

    // Animazione più lenta e fluida
    float slowTime = iTime * 0.15; // Movimento generale rallentato
    float a = smoothstep(0.0, 1.0, mod(slowTime, 1.0));

    // Rotazione più fluida
    mat2 rot = pow(SQRT3,-a)*mat2(
        cos(a*PI/8.0),-sin(a*PI/8.0), // Rallentato la rotazione
        sin(a*PI/8.0),cos(a*PI/8.0)
    );

    // Movimento più fluido del pattern
    float scale = 0.8 + 0.2*sin(slowTime * 0.5); // Oscillazione più lenta
    vec2 offset = vec2(
        0.1 * sin(slowTime * 0.3),
        0.1 * cos(slowTime * 0.4)
    );

    float temp = fractal(scale*rot*uv + vec2(0,0.5/SQRT3) + offset, 
                        smoothstep(0.0, 1.0, (a-0.1*a*a)/0.9));

    temp = mix(temp, 1.0-temp, smoothstep(0.0, 1.0, mod(slowTime, 2.0)));

    // Output finale con colori ciclici
    vec3 finalColor = temp < 0.0 ? col : mix(vec3(0.1), col, 0.15 + 0.1*temp);
    fragColor = vec4(finalColor, 1.0);
}
